/// The library's base. Its methods are the library's functions, and
/// each calls through the jump table.
pub const FacetBase = opaque {
    /// The Library header at the base.
    pub fn lib(self: *FacetBase) *libraries.Library {
        return @ptrCast(@alignCast(self));
    }

    /// A program's hold on the library, written to `instance`.
    pub fn CreateInstance(self: *FacetBase, info: *const facet.InstanceCreateInfo, instance: *?*facet.Instance) facet.Result {
        return libraries.call(self, LVO.CreateInstance, Fn.CreateInstance, .{ info, instance });
    }

    /// The instance given back: every device made from it destroyed first.
    pub fn DestroyInstance(self: *FacetBase, instance: ?*facet.Instance) void {
        return libraries.call(self, LVO.DestroyInstance, Fn.DestroyInstance, .{instance});
    }

    /// The physical devices into `devices`, at most `count.*` of them, and
    /// how many there are into `count`; null for `devices` counts alone.
    pub fn EnumeratePhysicalDevices(self: *FacetBase, instance: *facet.Instance, count: *u32, devices: ?[*]*facet.PhysicalDevice) facet.Result {
        return libraries.call(self, LVO.EnumeratePhysicalDevices, Fn.EnumeratePhysicalDevices, .{ instance, count, devices });
    }

    /// What the physical device is, into `properties`.
    pub fn GetPhysicalDeviceProperties(self: *FacetBase, physical: *facet.PhysicalDevice, properties: *facet.PhysicalDeviceProperties) void {
        return libraries.call(self, LVO.GetPhysicalDeviceProperties, Fn.GetPhysicalDeviceProperties, .{ physical, properties });
    }

    /// The device's queue families into `properties`, as
    /// EnumeratePhysicalDevices lists.
    pub fn GetPhysicalDeviceQueueFamilyProperties(self: *FacetBase, physical: *facet.PhysicalDevice, count: *u32, properties: ?[*]facet.QueueFamilyProperties) void {
        return libraries.call(self, LVO.GetPhysicalDeviceQueueFamilyProperties, Fn.GetPhysicalDeviceQueueFamilyProperties, .{ physical, count, properties });
    }

    /// The device's memory types and heaps, into `properties`.
    pub fn GetPhysicalDeviceMemoryProperties(self: *FacetBase, physical: *facet.PhysicalDevice, properties: *facet.PhysicalDeviceMemoryProperties) void {
        return libraries.call(self, LVO.GetPhysicalDeviceMemoryProperties, Fn.GetPhysicalDeviceMemoryProperties, .{ physical, properties });
    }

    /// A device of the program's own on `physical`, written to `device`, with
    /// a task for each queue.
    pub fn CreateDevice(self: *FacetBase, physical: *facet.PhysicalDevice, info: *const facet.DeviceCreateInfo, device: *?*facet.Device) facet.Result {
        return libraries.call(self, LVO.CreateDevice, Fn.CreateDevice, .{ physical, info, device });
    }

    /// The device given back, its queues' tasks ended: everything made from
    /// it destroyed first.
    pub fn DestroyDevice(self: *FacetBase, device: ?*facet.Device) void {
        return libraries.call(self, LVO.DestroyDevice, Fn.DestroyDevice, .{device});
    }

    /// Queue `index` of family `family`, written to `queue`.
    pub fn GetDeviceQueue(self: *FacetBase, device: *facet.Device, family: u32, index: u32, queue: *?*facet.Queue) void {
        return libraries.call(self, LVO.GetDeviceQueue, Fn.GetDeviceQueue, .{ device, family, index, queue });
    }

    /// A block of the device's memory, written to `memory`.
    pub fn AllocateMemory(self: *FacetBase, device: *facet.Device, info: *const facet.MemoryAllocateInfo, memory: *?*facet.DeviceMemory) facet.Result {
        return libraries.call(self, LVO.AllocateMemory, Fn.AllocateMemory, .{ device, info, memory });
    }

    /// The block given back: nothing bound to it in use any more.
    pub fn FreeMemory(self: *FacetBase, device: *facet.Device, memory: ?*facet.DeviceMemory) void {
        return libraries.call(self, LVO.FreeMemory, Fn.FreeMemory, .{ device, memory });
    }

    /// Where the memory is from `offset` on, `size` bytes of it (WHOLE_SIZE:
    /// to its end), written to `data`.
    pub fn MapMemory(self: *FacetBase, device: *facet.Device, memory: *facet.DeviceMemory, offset: u64, size: u64, flags: u32, data: *?*anyopaque) facet.Result {
        return libraries.call(self, LVO.MapMemory, Fn.MapMemory, .{ device, memory, offset, size, flags, data });
    }

    /// The mapping ended.
    pub fn UnmapMemory(self: *FacetBase, device: *facet.Device, memory: *facet.DeviceMemory) void {
        return libraries.call(self, LVO.UnmapMemory, Fn.UnmapMemory, .{ device, memory });
    }

    /// What the device does with `format` in each tiling and in a buffer,
    /// into `properties`.
    pub fn GetPhysicalDeviceFormatProperties(self: *FacetBase, physical: *facet.PhysicalDevice, format: facet.Format, properties: *facet.FormatProperties) void {
        return libraries.call(self, LVO.GetPhysicalDeviceFormatProperties, Fn.GetPhysicalDeviceFormatProperties, .{ physical, format, properties });
    }

    /// A buffer, with no memory yet, written to `buffer`.
